SELECT CAST(medicare2_2.bene_unique_cnt AS BIGINT) AS bene_unique_cnt__copy_,   CAST(medicare2_2.hcpcs_code AS BIGINT) AS hcpcs_code,   medicare2_2.hcpcs_description AS hcpcs_description,   CAST(medicare2_2.line_srvc_cnt AS BIGINT) AS line_srvc_cnt__copy_,   medicare2_2.nppes_provider_city AS nppes_provider_city,   medicare2_2.nppes_provider_first_name AS nppes_provider_first_name,   medicare2_2.nppes_provider_last_org_name AS nppes_provider_last_org_name,   medicare2_2.nppes_provider_street1 AS nppes_provider_street1,   CAST(medicare2_2.nppes_provider_zip AS BIGINT) AS nppes_provider_zip,   SUM((CAST(medicare2_2.average_medicare_payment_amt AS double precision) * CAST(CAST(medicare2_2.line_srvc_cnt AS BIGINT) AS double precision))) AS sum_total_medicare_payment__copy__ok,   (CAST(medicare2_2.average_medicare_payment_amt AS double precision) * CAST(CAST(medicare2_2.line_srvc_cnt AS BIGINT) AS double precision)) AS total_medicare_payment__copy_ FROM medicare2_2 WHERE ((medicare2_2.nppes_provider_state = 'NY') AND (medicare2_2.nppes_provider_country = 'US') AND (medicare2_2.provider_type = 'Allergy/Immunology')) GROUP BY medicare2_2.bene_unique_cnt,   medicare2_2.hcpcs_code,   medicare2_2.hcpcs_description,   medicare2_2.line_srvc_cnt,   medicare2_2.nppes_provider_city,   medicare2_2.nppes_provider_first_name,   medicare2_2.nppes_provider_last_org_name,   medicare2_2.nppes_provider_street1,   medicare2_2.nppes_provider_zip,   total_medicare_payment__copy_,   bene_unique_cnt__copy_,   hcpcs_code,   line_srvc_cnt__copy_,   nppes_provider_zip;
